UPDATE "source_value_extractions" SET "notes" = 'The ONLY extraction on this parameter that reports an OUTCOME against gradient rather than the slopes an apparatus was set to. Extractions 1 and 3 record 1:20/1:16/1:12/1:8 and 1:8-to-1:20 -- those are the test rigs, not findings, and a determination drawn from them alone would be a determination about experimental design. Read from the retrieved abstract (PMID 19236980, payload 498030d3f182cac1.xml), not from the paper''s full text; the 4-10 degree band is the authors'' own summary and the per-slope statistics behind it were not read. Direction matters: this is ASCENT only, which is why observation 37 kept ''upslope wheelchair stroking'' verbatim. || 2026-09-13 figure_role SET NULL -> finding (4 to 10 degrees is where load rose -- a finding about the parameter, not a recommended value) || 2026-09-13 comparator SET NULL -> between (a range between two degree values, not a point)', "updated_at" = '2026-09-13 02:52', "updated_by_session" = 'session_2026-09-13-backfill-figure-roles', "figure_role" = 'finding', "comparator" = 'between' WHERE "extraction_id" = 4;
